insert into public.restaurants (id, slug, name, tagline, logo_url, cover_url, about, address, phone, hours, theme, demo, created_at) values ('maison', 'maison', 'Maison', 'Haute gastronomie · Realidade aumentada à mesa', null, 'demo/cover.jpg', 'Sob o comando do chef-patron, a Maison une a técnica clássica francesa a ingredientes brasileiros de pequenos produtores. Menu sazonal, adega com mais de 600 rótulos e serviço de salão à moda antiga — agora com o cardápio que você vê sobre a sua própria mesa antes de pedir.', 'Alameda dos Jacarandás, 1200 — Jardins, São Paulo', '+55 11 4000-1200', 'Terça a sábado · 19h às 00h — Domingo · 12h às 16h', '{"background":"#0b0a09","surface":"#16130f","text":"#f4ecdf","accent":"#c9a45c","headingFont":"Cormorant Garamond","bodyFont":"Inter","radius":14}'::jsonb, true, '2026-11-15T12:00:00.000Z') on conflict (id) do nothing;
